contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // seedMin: value to set MinSum
    // seedDeposit: amount to deposit into c (sent as Ether)
    // collectAmt: amount to attempt to Collect
    function run(uint seedMin, uint seedDeposit, uint collectAmt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (seedDeposit)); require(seedDeposit <= 1000000000000000000000000000000);
        require(address(this).balance >= seedDeposit, "insufficient balance to fund deposit");

        // Configure MinSum before initialization
        c.SetMinSum(seedMin); if (__ESBMC_reverted()) return;

        // Make a deposit so this contract has a stored balance in c
        c.Deposit{value: seedDeposit}(); if (__ESBMC_reverted()) return;

        // Read observables before calling Collect
        uint beforeStored = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractBal = address(c).balance;

        // attempt Collect and record whether it reverted
        bool reverted;
        c.Collect(collectAmt); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterStored = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractBal = address(c).balance;

        // If Collect succeeded then (A) the caller's stored balance did not increase,
        // and (B) the drop in contract Ether balance is <= beforeStored (i.e., contract cannot send out more than caller's recorded balance).
        // To avoid underflow in expressing decreases, we write as afterContractBal + beforeStored >= beforeContractBal.
        assert(
            reverted || (
                // stored balance did not increase
                afterStored <= beforeStored
                &&
                // decrease in contract balance is at most beforeStored: beforeContractBal - afterContractBal <= beforeStored
                // rearranged to avoid underflow: afterContractBal + beforeStored >= beforeContractBal
                (afterContractBal + beforeStored >= beforeContractBal)
            )
        );
    }

    receive() external payable {}
}

