// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 seedMin, uint256 seedDeposit, uint256 collectAmt) internal {
        seedDeposit = bound(seedDeposit, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= seedDeposit);
        try c.SetMinSum(seedMin) {} catch { return; }
        try c.Deposit{value: seedDeposit}() {} catch { return; }
        uint256 beforeStored;
        try c.balances(address(this)) returns (uint256 __r) { beforeStored = __r; } catch { return; }
        uint beforeContractBal = address(c).balance;
        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterStored;
        try c.balances(address(this)) returns (uint256 __r) { afterStored = __r; } catch { return; }
        uint afterContractBal = address(c).balance;
        assertTrue(reverted || (
                // stored balance did not increase
                afterStored <= beforeStored
                &&
                // decrease in contract balance is at most beforeStored: beforeContractBal - afterContractBal <= beforeStored
                // rearranged to avoid underflow: afterContractBal + beforeStored >= beforeContractBal
                (afterContractBal + beforeStored >= beforeContractBal)
            ));
    }

    function testFuzz_run(uint256 seedMin, uint256 seedDeposit, uint256 collectAmt) public {
        _run(seedMin, seedDeposit, collectAmt);
    }

    receive() external payable {}
}
